async function grabSF(){GM_setValue('sfReq',Date.now());GM_deleteValue('sfRes');
 const tab=GM_openInTab('https://ams-amazon.lightning.force.com/lightning/app/06mat0000008EllAAE',{active:false,insert:true});
 try{for(let i=0;i<150;i++){await new Promise(r=>setTimeout(r,1000));const r=GM_getValue('sfRes');if(r&&r.at>=GM_getValue('sfReq'))return r;}
  return {ok:false,error:'没读到账户。请在浏览器里手动打开 Salesforce「Account 360 - UAT」首页，等表格加载出来后，再回来点一次「抓取账户」'};}finally{try{tab.close();}catch(e){}}}
