function openDB(job){const E=job?{b64:{shop:job.shop,cat:job.cat},ctx:{acct:job.acct,subv:job.subv,site:job.site,d1:job.d1?job.d1.replace(/-/g,'.'):'',d2:job.d2?job.d2.replace(/-/g,'.'):''},topN:'0',by:'cvr',lang:'cn'}:null;
 GM_setValue('amcDbJob',{E,at:Date.now()});
 try{GM_openInTab(DB_URL+'-'+Date.now(),{active:true,insert:true});}catch(e){}
 // 兜底：面板里保留打开按钮 + 下载 HTML
 const html=buildDbHtml(E);const name=((job&&job.acct)||'AMC').replace(/[\/\\:*?"<>|]/g,'_')+'_AMC_Pulse看板.html';
 const box=document.querySelector('#amc-root #amc-status');
 if(box)setTimeout(()=>{if(!/已打开/.test(box.textContent))return;const b=document.createElement('button');b.className='btn';b.style.marginTop='6px';b.textContent='没看到新窗口？点此打开 / 下载看板';
  b.onclick=()=>{try{GM_openInTab(DB_URL+'-'+Date.now(),{active:true});}catch(e){}const u=URL.createObjectURL(new Blob([html],{type:'text/html;charset=utf-8'}));const a=document.createElement('a');a.href=u;a.download=name;document.body.appendChild(a);a.click();a.remove();};box.appendChild(b);},1500);
 return 'tab';}

