let reqId=0;const pend={};
const call=(cmd,args)=>new Promise((res,rej)=>{const id=++reqId;pend[id]={res,rej};window.postMessage(JSON.stringify({__amc2:'req',id,cmd,args}),'*');});
const pm=e=>{if(typeof e.data!=='string')return null;try{return JSON.parse(e.data)}catch(x){return null}};
window.addEventListener('message',e=>{const m=pm(e);if(m&&m.__amc2==='res'&&pend[m.id]){m.ok?pend[m.id].res(m.data):pend[m.id].rej(m.data);delete pend[m.id];}});
